import React, { useEffect, useState } from 'react';
import api from '../api';
import Sidebar from '../components/Sidebar';
import Profile from './Profile';
import Payments from './Payments';
import Logout from '../components/Logout';
import './AdminPanel.css';

export default function AdminPanel() {
  const [deposits, setDeposits] = useState([]);
  const [fund, setFund] = useState(null);
  const [view, setView] = useState('dashboard');

  useEffect(() => {
    api.get('/payments/').then(r => setDeposits(r.data)).catch(() => {});
    api.get('/funds/').then(r => setFund(r.data)).catch(() => {});
  }, []);

  const confirm = async (id) => {
    await api.post(`/deposits/${id}/confirm/`, {});
    alert('تأیید شد');
    window.location.reload();
  };

  const renderContent = () => {
    if (view === 'profile') return <Profile />;
    if (view === 'payments') return <Payments />;
    if (view === 'logout') return <Logout />;
    return (
      <div>
        {fund && (
          <div className="fund-info">
            <h2>{fund.name}</h2>
            <p>مدیر: {fund.manager_name}</p>
            <p>موجودی فعلی: {fund.current_balance.toLocaleString()} تومان</p>
          </div>
        )}
        <h4>واریزها</h4>
        <ul>
          {deposits.map(d => (
            <li key={d.id}>
              {d.user} - {d.amount} - {d.manager_confirmed ? 'تأیید شده' : <button onClick={() => confirm(d.id)}>تأیید</button>}
            </li>
          ))}
        </ul>
      </div>
    );
  };

  return (
    <div className="admin-panel">
      <Sidebar onSelect={setView} />
      <div className="main-content" style={{direction:'rtl', padding:20}}>
        {renderContent()}
      </div>
    </div>
  );
}
